mapper.select:
SELECT T.PARAM_NO, T.PARAM_ITEM_NO, T.DEFAULT_VAL, PI.PARAM_ITEM_ID, SY.CONTENT AS PARAM_NAME, T.DISTINCT_FIELD, T.DISTINCT_FIELD_2ND, SY1.CONTENT AS DISTINCT_FIELD_NAME, SY2.CONTENT AS DISTINCT_FIELD_2ND_NAME FROM PA_PARAM_ITEM_PARAM T, PA_PARAM_ITEM PI, SY_GLOBAL_NAME SY, PA_DISTINCT_LIST PA1, PA_DISTINCT_LIST PA2, SY_GLOBAL_NAME SY1, SY_GLOBAL_NAME SY2 WHERE T.PARAM_ITEM_NO = PI.PARAM_ITEM_NO AND T.DISTINCT_FIELD = PA1.DISTINCT_FIELD(+) AND T.CPNY_ID = PA1.CPNY_ID(+) AND PA1.ID = SY1.NO(+) AND SY1.LANGUAGE(+) = #{lang, jdbcType=VARCHAR} AND T.DISTINCT_FIELD_2ND = PA2.DISTINCT_FIELD(+) AND T.CPNY_ID = PA2.CPNY_ID(+) AND PA2.ID = SY2.NO(+) AND SY2.LANGUAGE(+) = #{lang, jdbcType=VARCHAR} AND T.PARAM_ITEM_NO = SY.NO AND SY.LANGUAGE = #{lang, jdbcType=VARCHAR} AND PI.ACTIVITY = 1
AND PI.ITEM_TYPE = #{itemType, jdbcType=VARCHAR}
AND T.ACTIVITY = '1' AND T.CPNY_ID = #{cpnyId, jdbcType=VARCHAR} ORDER BY PI.ORDER_NO

SELECT COUNT(1) FROM PA_PARAM_DATA A, PA_PARAM_ITEM_PARAM C WHERE A.PARAM_NO = #{paramNo, jdbcType=VARCHAR} AND A.PERSON_ID = #{personId, jdbcType=VARCHAR} AND A.CPNY_ID = #{cpnyId, jdbcType=VARCHAR} AND A.ACTIVITY = 1 AND NVL(A.REMARK, ' ') <> 'Employee Resign' AND NVL(A.CREATED_BY, ' ') <> 'BEFORE_CAL'
AND A.PARAM_DATA_NO <> #{paramDataNo, jdbcType=NUMERIC}
AND A.START_DATE <= NVL(TO_DATE(#{endDate, jdbcType=VARCHAR}, 'YYYY-MM-DD'), DATE '9999-12-31') AND NVL(A.END_DATE, DATE '9999-12-31') >= TO_DATE(#{startDate, jdbcType=VARCHAR}, 'YYYY-MM-DD') AND C.PARAM_NO = A.PARAM_NO AND C.CPNY_ID = A.CPNY_ID AND NVL(C.PRORATE_TYPE, 0) IN (2, 3)

mapper.delete:
UPDATE PA_PARAM_DATA
   SET ACTIVITY = 0,
       UPDATED_BY  = #{adminID, jdbcType=VARCHAR},
       UPDATE_DATE = SYSDATE,
       UPDATED_IP  = #{adminIP, jdbcType=VARCHAR}
 WHERE PARAM_DATA_NO = #{paramDataNo, jdbcType=NUMERIC}

mapper.select:
SELECT PARAM_DATA_NO, PARAM_NO, FIELD1_VALUE, FIELD2_VALUE, FIELD1_NAME, FIELD2_NAME,
       RETURN_VALUE, START_MONTH, END_MONTH, START_DATE, END_DATE, CPNY_ID, REMARK
  FROM (
    SELECT a.*, ROWNUM AS RN
      FROM (

        ORDER BY FIELD1_NAME, FIELD2_NAME, A.START_DATE
      ) a
     WHERE ROWNUM <= #{start, jdbcType=NUMERIC} + #{length, jdbcType=NUMERIC}
  )
 WHERE RN > #{start, jdbcType=NUMERIC}

mapper.update:
UPDATE PA_PARAM_DATA_OTHER
   SET ACTIVITY    = 0,
       UPDATED_BY  = #{adminID, jdbcType=VARCHAR},
       UPDATE_DATE = SYSDATE,
       UPDATED_IP  = #{adminIP, jdbcType=VARCHAR}
 WHERE PARAM_DATA_NO = #{paramDataNo, jdbcType=NUMERIC}

mapper.select:
SELECT COUNT(1) FROM PA_PARAM_DATA_OTHER A, PA_PARAM_ITEM_PARAM C WHERE A.PARAM_NO = #{paramNo, jdbcType=VARCHAR} AND A.CPNY_ID = #{cpnyId, jdbcType=VARCHAR} AND A.ACTIVITY = 1 AND A.FIELD1_VALUE = #{field1Value, jdbcType=VARCHAR} AND NVL(A.FIELD2_VALUE, '#') = NVL(#{field2Value, jdbcType=VARCHAR}, '#')
AND A.PARAM_DATA_NO <> #{paramDataNo, jdbcType=NUMERIC}
AND A.START_DATE <= NVL(TO_DATE(#{endDate, jdbcType=VARCHAR}, 'YYYY-MM-DD'), DATE '9999-12-31') AND NVL(A.END_DATE, DATE '9999-12-31') >= TO_DATE(#{startDate, jdbcType=VARCHAR}, 'YYYY-MM-DD') AND C.PARAM_NO = A.PARAM_NO AND C.CPNY_ID = A.CPNY_ID AND NVL(C.PRORATE_TYPE, 0) IN (2, 3)

